contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 price, uint256 supply, uint16 allowance, uint256 quantity) public payable {
        address self = address(this);
        c.adjustAdminAccess(self, true);
        c.createGameItem("pbt", "uri", true, true, supply, price, allowance);
        uint256 tokenId = c.uniqueTokensOutstanding() - 1;
        uint256 beforeBalance = c.balanceOf(self, tokenId);
        uint256 beforeRemaining = c.remainingSupply(tokenId);
        uint256 beforeTotal = c.balanceOf(treasuryAddress(), tokenId);

        (bool ok, ) = address(c).call(abi.encodeWithSignature("mint(uint256,uint256)", tokenId, quantity));

        uint256 afterBalance = c.balanceOf(self, tokenId);
        uint256 afterRemaining = c.remainingSupply(tokenId);
        uint256 afterTotal = c.balanceOf(treasuryAddress(), tokenId);

        bool shouldSucceed = price > 0 && quantity <= allowance && quantity <= supply;
        assert(
            (ok && shouldSucceed && afterBalance == beforeBalance + quantity && afterRemaining == beforeRemaining - quantity && afterTotal == beforeTotal) ||
            (!ok && (!shouldSucceed || price == 0 || beforeBalance + quantity < beforeBalance))
        );
    }

    function treasuryAddress() internal view returns (address) {
        (bool success, bytes memory data) = address(c).staticcall(abi.encodeWithSignature("treasuryAddress()"));
        require(success);
        return abi.decode(data, (address));
    }

    receive() external payable {}
}

