contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address user,
        uint256 itemPrice,
        uint256 dailyAllowance,
        uint256 nrnLiquidity
    ) public payable {
        require(user != address(0));
        require(user != address(this));
        require(itemPrice > 0);
        require(dailyAllowance > 0);

        address treasury = c.treasuryAddress();

        Neuron nrn = new Neuron(address(this), address(this), address(this));
        nrn.addMinter(address(this));
        nrn.mint(user, nrnLiquidity);
        c.instantiateNeuronContract(address(nrn));

        nrn.approve(user, type(uint256).max);
        nrn.approveSpender(user, type(uint256).max);

        c.createGameItem("item", "uri", false, true, 0, itemPrice, uint16(dailyAllowance));
        uint256 tokenId = c.uniqueTokensOutstanding() - 1;

        uint256 userBalanceBefore = c.balanceOf(user, tokenId);
        uint256 allowanceBefore = c.getAllowanceRemaining(user, tokenId);
        uint256 treasuryNrnBefore = nrn.balanceOf(treasury);

        bool reverted;
        try c.mint(tokenId, 1) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 userBalanceAfter = c.balanceOf(user, tokenId);
            uint256 allowanceAfter = c.getAllowanceRemaining(user, tokenId);
            uint256 treasuryNrnAfter = nrn.balanceOf(treasury);
            assert(
                userBalanceAfter == userBalanceBefore + 1 &&
                allowanceAfter == allowanceBefore - 1 &&
                treasuryNrnAfter == treasuryNrnBefore + itemPrice
            );
        } else {
            assert(false);
        }
    }

    receive() external payable {}
}

