contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        string memory itemName,
        string memory tokenURI,
        bool finiteSupply,
        uint256 itemsRemaining,
        uint256 itemPrice,
        uint16 dailyAllowance,
        uint256 buyerPrivateKey,
        uint256 mintAmount
    ) public payable {
        require(mintAmount == 1);

        address buyer = vm.addr(buyerPrivateKey);
        require(buyer != address(0));

        vm.deal(buyer, 0);

        // Create a non-transferable item and make it purchasable
        c.createGameItem(itemName, tokenURI, finiteSupply, false, itemsRemaining, itemPrice, dailyAllowance);

        // Fund buyer with enough NRN if possible
        uint256 totalCost = itemPrice * mintAmount;
        if (totalCost > 0) {
            // Cannot mint NRN out of thin air; skip rule if price > 0 because buyer cannot pay
            return;
        }

        uint256 balanceBefore = c.balanceOf(buyer, 0);

        vm.prank(buyer);
        c.mint(0, mintAmount);

        uint256 balanceAfter = c.balanceOf(buyer, 0);

        assert(balanceAfter == balanceBefore + mintAmount);
    }

    receive() external payable {}
}
